import {mountLeaderboard} from '../shared/leaderboard.mjs';
import {recordPlayStart} from '../shared/play-counts.mjs';
let leaderboard=null;
import {createSceneAudio} from '../shared/scene-audio.mjs';
import {createGameAudioEvents} from '../shared/game-audio-events.mjs';
import {mountControlsFrame} from '../shared/controls-shell.mjs';
mountControlsFrame({document,game:"high-jump",scene:document.querySelector("#stage"),controls:document.querySelector(".controls"),keys:{a:document.querySelector("#a"),s:document.querySelector("#s"),j:document.querySelector("#j"),k:document.querySelector("#k")}});
import {createGameEntry,helpIsOpen,suspendHelpPresentation,ensurePauseHelp} from '../shared/entry-shell.mjs';
import {selectReplay,replayFrame} from './replay.mjs';
import {createRenderTransaction} from './render-transaction.mjs';
import {bindControls} from './control-bindings.mjs';
import {createActionInputs} from './action-inputs.mjs';
import {createPresentationClock} from './clock.mjs';
import {createRound,advance,verdict,KEYS,snapshot} from './physics.mjs';
import {createWorld} from './render.mjs';import {syncPauseButton,createResultDialog,createMusicController} from '../shared/game-ui.mjs';import {createSharing} from './share.mjs';
const $=id=>document.getElementById(id);let initialPresentationReady=false,world=null,s=createRound(),active=false,record=[],replay=null,replayClip=null,last=0,completed=false,pendingFinish=false;const clock=createPresentationClock(evolve,()=>pause(true,'畫面更新延遲，已保留剛才可見的位置。繼續後再操作，不會暗判漏步或失誤。'));const controls=createActionInputs(()=>s,()=>clock.input(performance.now()),paintControls);let best=0;try{best=Number(localStorage.getItem('pf-high-jump-best-v8'))||0}catch{}$('best').textContent=best?best.toFixed(1)+' m':'—';
const presentation=createRenderTransaction({getState:()=>s,setState:value=>{s=value;pendingFinish=false;completed=false;},getMeta:()=>({replay,active,completed}),setMeta:m=>{replay=m.replay;active=m.active;completed=m.completed;},getHistoryLength:()=>record.length,truncateHistory:n=>{record.length=n;},onError:error=>{pendingFinish=false;pause(true,'繪圖暫時失敗，已保留上一個成功畫面的位置。按繼續重試；重來也可以。');$('status').textContent='繪圖未成功，沒有計分；可重試。';console.warn('High-jump draw interrupted',error);}});
presentation.seed();
function drawSafely(shown,commit=()=>{}){return presentation.draw(()=>{world.resize();world.draw(shown);},commit);}
const music=createSceneAudio({game:'high-jump',src:new URL('./audio/bgm.mp3',import.meta.url).href,notify:a=>{$('music').setAttribute('aria-pressed',String(a.ready));$('music').setAttribute('aria-label',a.enabled&&a.ready?'關閉音樂':'開啟或重試音樂');$('music').textContent=a.ready?'♫ 開':'♫ 關';if(a.pending)$('status').textContent='音樂載入中…';else if(a.ready)$('status').textContent='音樂已開啟 · 不用配合音樂打拍子。';else if(a.enabled&&!a.ready&&active)$('status').textContent='音樂尚未開啟；可按音樂重試。不影響遊戲。';}});
const audioEvents=createGameAudioEvents('high-jump',name=>music.play(name));
const sharing=createSharing({byId:$});const result=createResultDialog($('result'),{focusTarget:()=>$('retry'),returnFocus:()=>$('stage')});
function paintControls(){for(const key of KEYS)$(key.toLowerCase()).classList.toggle('active',controls.isHeld(key));}
function release(){bindings.release();}
function audioUnlock(){music.setPlaying(true);void music.unlock()}
function start(){if(!initialPresentationReady)return;leaderboard?.reset();entry.close({restoreView:false});release();sharing.reset();for(const id of['intro','paused','result','fallback'])if($(id).open)$(id).close();s=createRound();s.phase='run';s.countdown=0;audioEvents.reset();audioEvents.update(s,{emitResult:false});active=true;clock.reset(performance.now());completed=false;pendingFinish=false;record=[];replay=null;replayClip=null;presentation.seed();last=0;$('replayTag').hidden=true;$('status').textContent='誇張運動，請勿模仿。';audioUnlock();$('stage').focus({preventScroll:true});update();void recordPlayStart(window,'high-jump');}
function pause(value=true,reason='遊戲時間已停住，繼續後重新按鍵。'){if(!active||s.phase==='done'&&!replay)return;if(value)clock.pause(performance.now());else clock.resume(performance.now());if(!active)return;release();s.paused=value;last=0;music.setPlaying(!value);if(value){$('pauseReason').textContent=reason;if(!helpIsOpen(document))entry.openPause();}else{entry.close({restoreView:false});if($('paused').open)$('paused').close();audioUnlock();$('stage').focus({preventScroll:true});}update();}
function finish(){leaderboard?.setResult({...s,phase:'done'});completed=true;release();active=false;music.setPlaying(false);audioEvents.finish();const rating=s.resultVerdict=verdict(s);if(record.at(-1)?.t!==s.t)record.push(snapshot(s));if(s.success&&s.height>best){best=s.height;try{localStorage.setItem('pf-high-jump-best-v8',String(best))}catch{}}$('best').textContent=best?best.toFixed(1)+' m':'—';$('resultTitle').textContent=s.success?'越過去了！':s.fallen?'重心先下班了':'再來一跳？';$('resultScore').textContent=s.success?s.height.toFixed(1)+' m':'未過桿';$('verdict').textContent=rating;result.open();captureResult();update();}
function captureResult(){sharing.capture(world.canvas,s,s.resultVerdict,(w,h)=>world.capture(s,w,h));}
function update(){const shown=replay?replayFrame(replayClip,replay.time)||s:s;$('target').textContent=shown.barLocked||shown.phase==='air'?shown.target.toFixed(1)+' m':'起跳後決定';$('count').textContent=active&&!replay&&s.phase==='countdown'?Math.ceil(s.countdown):'';
 $('prompt').textContent=replay?'看這一跳，手腳怎麼配合。':s.phase==='countdown'?'A/S 控制雙腳，長按 A 或 S 蓄力，放開起跳；J/K 雙手平衡':s.phase==='run'?'A/S 控制雙腳，長按 A 或 S 蓄力，放開起跳；J/K 雙手平衡':s.phase==='air'?'先按 J/K 帶頭肩過桿；髖過桿後按 A/S 收腿。':s.feedback;
 syncPauseButton($('pause'),{paused:s.paused,available:active&&s.phase!=='done'||Boolean(replay)});for(const key of KEYS)$(key.toLowerCase()).disabled=!active||s.paused||!!replay;paintControls();return shown;}
$('start').onclick=()=>start();$('restart').onclick=()=>start();$('retry').onclick=()=>start();$('pause').onclick=()=>pause(!s.paused);$('resume').onclick=()=>pause(false);$('paused').addEventListener('cancel',e=>{e.preventDefault();pause(false)});$('intro').addEventListener('cancel',e=>e.preventDefault());
$('music').onclick=()=>{if(music.ready){music.setEnabled(false);$('status').textContent='音樂已關閉。';}else{music.setEnabled(true);music.setPlaying(active&&!s.paused);void music.unlock()}};
$('replay').onclick=()=>{result.close();release();const clip=selectReplay(record);if(!clip){result.open();return;}replayClip=clip;replay={time:0};active=true;s.paused=false;presentation.seed();clock.reset(performance.now());last=0;$('replayTag').hidden=false;$('stage').focus({preventScroll:true});update();};
const bindings=bindControls({buttons:Object.fromEntries(KEYS.map(k=>[k,$(k.toLowerCase())])),global:globalThis,input:controls,available:()=>active&&!s.paused&&!replay,changed:update});
addEventListener('keydown',e=>{if(!e.repeat&&['p','P','Escape'].includes(e.key)&&active&&!$('result').open&&!$('intro').open){e.preventDefault();pause(!s.paused);}});

function interrupt(){if(active)pause(true);else release()}addEventListener('blur',interrupt);document.addEventListener('visibilitychange',()=>{if(document.hidden)interrupt()});addEventListener('orientationchange',interrupt);globalThis.screen?.orientation?.addEventListener('change',interrupt);addEventListener('resize',()=>{try{world?.resize();if(world)drawSafely(update());if($('result').open&&completed)captureResult();}catch(error){pause(true,'畫面調整失敗，按繼續重試。');$('status').textContent='畫面未成功更新，沒有計分。';}});
try{world=createWorld($('world'));initialPresentationReady=drawSafely(s)}catch(error){$('world').innerHTML='<div class="game-error"><b>這個瀏覽器目前無法啟動 WebGL。</b><br>遊戲尚未開始，也不會計分。請改用支援 WebGL 的瀏覽器，或返回遊戲首頁。</div>';$('restart').disabled=true;for(const key of KEYS)$(key.toLowerCase()).disabled=true;$('status').textContent='3D 畫面無法啟動；首頁與音樂按鈕仍可使用。';console.error('High-jump renderer unavailable',error)}
if(!initialPresentationReady)$('restart').disabled=true;
function evolve(dt){if(!world||!active||s.paused)return;if(replay){replay.time+=dt;if(replay.time>=replayClip.duration){replay=null;active=false;$('replayTag').hidden=true;drawSafely(s,()=>result.open());}return;}let remaining=dt;while(remaining>1e-9&&active){const step=Math.min(remaining,1/120),before=s.t;advance(s,step);if(Math.floor(s.t*60)>Math.floor(before*60))record.push(snapshot(s));remaining-=step;if(s.phase==='done'&&!completed){pendingFinish=true;break;}}}
function frame(){try{const now=performance.now(),ready=active?clock.frame(now):false;const shown=update();if(world&&active&&!s.paused&&ready)drawSafely(shown,()=>{clock.present(now);if(!replay)audioEvents.update(s,{emitResult:false});if(pendingFinish){pendingFinish=false;finish();}});}catch(error){s.paused=true;clock.pause?.();try{pause(true,'繪圖暫時失敗，按繼續或重來再試。');}catch{}}finally{requestAnimationFrame(frame)}}requestAnimationFrame(frame);

function helpVisit(){leaderboard?.suspend();return suspendHelpPresentation(document,{pause:()=>{interrupt();release();},controllers:{result},dialogs:['paused','result','intro'],after:({restoredDialog})=>{if(!restoredDialog&&active&&s.paused&&(s.phase!=='done'||replay))entry.openPause();}});}
const entry=createGameEntry({document,gameId:'high-jump',operations:['助跑：A／S 交替短按，搭配 J／K 擺動手臂、調整平衡。','起跳：長按 A 或 S 蓄力，在綠區放開起跳。','過桿：先按 J／K 帶頭肩過桿，髖部過桿後按 A／S 收腿。'],onHelpEnter:helpVisit,onStart:()=>start(),onEnter:()=>{interrupt();release();},canStart:()=>initialPresentationReady});entry.open();

entry.setAudio(music);

entry.configurePause({onContinue:()=>pause(false),onRestart:()=>start(),canContinue:()=>active&&s.paused});

leaderboard=mountLeaderboard({document,game:'high-jump',entry:entry.dialog,shell:entry,result:$('result')});

:root{font-family:Arial,'Noto Sans TC',system-ui,sans-serif;color:#203f3a;background:#f5f0df}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overscroll-behavior:none}button,a{-webkit-tap-highlight-color:transparent;touch-action:manipulation}button{font:inherit;cursor:pointer}button:disabled{opacity:.45}button:focus-visible,a:focus-visible{outline:3px solid #dc693d;outline-offset:2px}
/* One active layout, scoped above shared admission styles. No legacy active/phase overrides. */
.pf-game.pf-high-jump .app{height:100dvh;min-height:0;max-width:1600px;margin:auto;padding:calc(8px + env(safe-area-inset-top)) calc(8px + env(safe-area-inset-right)) calc(8px + env(safe-area-inset-bottom)) calc(8px + env(safe-area-inset-left));display:grid;grid-template-rows:auto minmax(0,74fr) minmax(124px,26fr);gap:6px;overflow:hidden}
.pf-high-jump .pf-header h1 span{font-size:11px;font-weight:400}
.pf-game.pf-high-jump #stage{position:relative;overflow:hidden;min-height:0;min-width:0;border:1px solid #b9cfc0;border-radius:16px;background:#badbd0}
#world,#world canvas{width:100%;height:100%;display:block}.stage-label{position:absolute;left:12px;top:10px;font-size:12px;background:#fff9e5dd;padding:5px 8px;border-radius:8px}.stage-label span{display:inline-block;margin-left:10px;font-size:10px}.stage-label button{border:0;background:transparent;color:inherit;min-height:28px;min-width:28px}#count{position:absolute;left:50%;top:45%;transform:translate(-50%,-50%);font-size:90px;font-weight:900;color:#fff9d7;text-shadow:0 5px #39766a;pointer-events:none}#replayTag{position:absolute;right:12px;top:12px;background:#203f3a;color:#fff5dc;padding:8px;border-radius:6px;font-size:12px}
.control-panel{display:flex;flex-direction:column;justify-content:center;gap:10px;min-height:0;min-width:0}#prompt{margin:0;text-align:center;font-size:14px;line-height:1.4}.controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(20px,8vw,100px);min-width:0}.limb-group{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;min-width:0}.controls button{min-width:0;min-height:52px;border:1px solid #aab8a1;border-radius:12px;background:#fff9e6;color:#284f44;font-size:15px;font-weight:700;touch-action:none;user-select:none;overflow:hidden}.controls button.active{background:#f3aa65;transform:translateY(2px)}.controls kbd{font:700 15px Arial;margin-right:6px}.status{font-size:10px;color:#718172;text-align:center;margin:0;line-height:1.3}.eyebrow{font-size:10px;letter-spacing:2px;color:#748371}
dialog{position:fixed;width:min(480px,calc(100vw - 28px));max-height:calc(100dvh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom));border:1px solid #bac7ac;border-radius:22px;padding:30px;background:#fff9e8;color:#23453c;overflow:auto;overscroll-behavior:contain;touch-action:pan-y;box-shadow:0 15px 80px #173b3f40}dialog::backdrop{background:#173b3f66;backdrop-filter:blur(4px)}dialog h2{font-size:35px;line-height:1.25;margin:8px 0 18px;letter-spacing:-1px}dialog p,dialog li{font-size:14px;line-height:1.7}dialog ol{padding-left:22px}dialog li{margin:12px 0}dialog button,.result-actions button{min-height:46px;border-radius:9px;border:1px solid #b1bd9c;padding:10px 15px;background:#f1efd9;color:#27463a;font-weight:700}.primary{background:#2d6e53!important;color:#fffbe4!important;border-color:#2d6e53!important}#start{width:100%;margin-top:10px}.result-score{font-size:56px;font-weight:900;color:#d86b38}.result-actions{display:flex;gap:8px;flex-wrap:wrap}#resultPhoto,#fallbackImage{width:100%;border-radius:10px}#fallback textarea{width:100%;min-height:150px;font:inherit;padding:10px;user-select:text}.lead{color:#6a7865}.pf-share-actions a{min-height:44px;text-decoration:none;display:flex;align-items:center;justify-content:center}#shareStatus{min-height:20px;font-size:12px}.game-error{padding:70px 25px;line-height:1.8}

@media(max-width:640px){.pf-game.pf-high-jump .pf-header{grid-template-columns:auto minmax(0,1fr);min-height:44px}.pf-game.pf-high-jump .pf-header nav{justify-self:end}.pf-game.pf-high-jump .pf-header nav button{font-size:12px;padding:0 5px}.pf-game.pf-high-jump .pf-header .pf-home{font-size:12px;padding:0 5px}.controls{gap:24px}.limb-group{gap:5px}.controls button{padding:5px 1px;font-size:13px}.controls kbd{margin-right:3px}#prompt{font-size:13px}.status{font-size:9px}}
@media(max-height:500px){.control-panel{gap:4px}.controls button{min-height:44px}#prompt{font-size:12px}.status{display:none}.pf-game.pf-high-jump .app{grid-template-rows:auto minmax(0,74fr) minmax(64px,26fr)}}

/* The download photo keeps its own aspect; optional result content scrolls instead of squeezing it. */
.pf-game.pf-high-jump #result{width:min(720px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));height:fit-content;max-height:calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));padding:16px;display:flex;flex-direction:column;gap:10px;overflow:auto;scrollbar-gutter:stable;align-items:stretch}
.pf-game.pf-high-jump #result>*{flex-shrink:0}
.pf-game.pf-high-jump #result .result-summary{min-width:0;text-align:center}
.pf-game.pf-high-jump #result .eyebrow{font-size:10px;line-height:1.2;margin:0 0 3px}
.pf-game.pf-high-jump #result h2{font-size:21px;line-height:1.2;margin:0 0 3px}
.pf-game.pf-high-jump #result .result-score{font-size:clamp(30px,5vh,46px);line-height:1.08}
.pf-game.pf-high-jump #result #verdict{font-size:14px;line-height:1.35;margin:5px 0 0;overflow-wrap:anywhere}
.pf-game.pf-high-jump #result .result-scene{min-height:0;min-width:0;display:flex;align-items:center;justify-content:center}
.pf-game.pf-high-jump #result #resultPhoto{width:auto;height:auto;max-width:100%;max-height:300px;min-height:0;object-fit:contain;background:#beded1;border-radius:12px}
.pf-game.pf-high-jump #result .result-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:0;min-width:0}
.pf-game.pf-high-jump #result .result-actions button{font-size:15px;min-width:0;min-height:44px;padding:8px}
.pf-game.pf-high-jump #result .pf-share-actions{grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.pf-game.pf-high-jump #result .pf-share-actions :is(button,a){font-size:12px;min-height:44px;padding:6px 4px}
.pf-game.pf-high-jump #result #shareStatus{font-size:11px;line-height:1.25;margin:0;min-height:0;text-align:center}
.pf-game.pf-high-jump #result #shareStatus:empty{display:none}
.pf-game.pf-high-jump #result #retryImage{font-size:12px;min-height:36px;padding:4px}
@media(max-height:500px) and (min-width:600px){
 .pf-game.pf-high-jump #result{width:min(860px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));padding:12px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);grid-template-rows:auto auto auto;grid-auto-rows:max-content;gap:8px 12px;align-content:start}
 .pf-game.pf-high-jump #result .result-summary{grid-column:1;grid-row:1;align-self:center}
 .pf-game.pf-high-jump #result .result-scene{grid-column:2;grid-row:1/3}
 .pf-game.pf-high-jump #result #resultPhoto{max-height:240px}
 .pf-game.pf-high-jump #result .result-actions{grid-column:1;grid-row:2}
 .pf-game.pf-high-jump #result .pf-share-actions{grid-column:1/-1;grid-row:3}
 .pf-game.pf-high-jump #result #shareStatus{grid-column:1/-1;grid-row:4}
 .pf-game.pf-high-jump #result #retryImage{grid-column:1/-1}
 .pf-game.pf-high-jump #result :is(.pf-result-ranking,.pf-leaderboard){grid-column:1/-1}
}

/* Explicit persistent instructions, never removed when running starts. */
.pf-game.pf-high-jump #prompt{display:block!important;visibility:visible;flex-shrink:0;overflow-wrap:anywhere}

/* Desktop tickets use the available width; touch/mobile keeps the existing layout. */
@media (min-width:900px) and (hover:hover) and (pointer:fine){
 .pf-game.pf-high-jump dialog.pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog){width:min(1000px,calc(100vw - 32px))!important;padding:18px!important;}
 .pf-game.pf-high-jump dialog.pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)[open]{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 16px;align-content:start;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>.pf-menu-ticket{grid-column:1/-1;margin:-18px -18px 0!important;padding:14px 20px!important;grid-template-columns:minmax(0,1fr) 64px;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>.pf-menu-ticket>img{width:64px;height:64px;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>.pf-menu-ticket h2{font-size:26px!important;margin:4px 0!important;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>.pf-entry-goal{grid-column:1/-1;margin:0!important;font-size:18px!important;line-height:1.5!important;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>.pf-entry-operations{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog) .pf-entry-operation{min-width:0;margin:0!important;padding:12px;border:1px solid #c4d1b7;border-radius:14px;background:#f5f0d9;font-size:16px!important;line-height:1.55!important;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>details{min-width:0;margin:0!important;align-self:start;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>details>summary{margin:0;min-height:52px;padding:10px 15px;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>.pf-entry-start{margin:0!important;align-self:start;}
 .pf-game.pf-high-jump .pf-entry:not(.pf-pause-dialog):not(.pf-honor-dialog)>:is(.pf-leaderboard,.pf-entry-error){grid-column:1/-1;}
 .pf-game.pf-high-jump #result{width:min(1080px,calc(100vw - 32px - env(safe-area-inset-left) - env(safe-area-inset-right)));padding:18px;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(320px,1fr);grid-template-rows:repeat(8,auto);grid-auto-rows:max-content;gap:10px 20px;align-content:start;}
 .pf-game.pf-high-jump #result .result-scene{grid-column:1;grid-row:1/8;align-self:start;}
 .pf-game.pf-high-jump #result #resultPhoto{max-height:400px;}
 .pf-game.pf-high-jump #result .result-summary{grid-column:2;grid-row:1;text-align:left;}
 .pf-game.pf-high-jump #result .result-actions{grid-column:2;grid-row:2;}
 .pf-game.pf-high-jump #result .pf-share-actions{grid-column:2;grid-row:3;}
 .pf-game.pf-high-jump #result #shareStatus{grid-column:2;grid-row:4;text-align:left;}
 .pf-game.pf-high-jump #result #retryImage{grid-column:2;grid-row:5;}
 .pf-game.pf-high-jump #result .pf-result-ranking{grid-column:2;grid-row:6;margin:0;font-size:16px;}
 .pf-game.pf-high-jump #result .pf-leaderboard{grid-column:2;grid-row:7;margin:0;padding:10px;}
 .pf-game.pf-high-jump #result .pf-leaderboard>summary{font-size:16px;}
 .pf-game.pf-high-jump #result .pf-studio-result{grid-column:1/-1;grid-row:8;margin:0;}
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {JSDOM} from 'jsdom';
import postcss from 'postcss';
