 assert.equal(sha(JSON.stringify(pins.RESULT_UPLOAD_BASE_BLOBS)),'4c2ad7443c79f375db5e3beba76dc7025fc7cb3caff5a72b758a828ef0d24fe3','Published recursive-tree pin set remains independent of the new manifest');
